// ***************
// Filename: gpio_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of gpio: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to gpio's logic on named ports, its status
//   comes back on input ports. General purpose I/O: direction, output with
//   atomic set / clear / toggle, synchronised inputs, edge interrupts.
//   Generated by ip/scripts/regmap_gen.py from gpio_regs.json: edit the JSON
//   and regenerate (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "GPIO" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 OUT         CMD  output register: reads the pin output values, a
//                       write sets them all
//     0x14 DIR         RW   direction per pin, 1 = output (0 = input, pad
//                       high-Z), reset 0x0
//     0x18 IN          RO   pin levels (two-flop synchronised)
//     0x1C SET         WO   write 1s: set those OUT bits (atomic)
//     0x20 CLEAR       WO   write 1s: clear those OUT bits (atomic)
//     0x24 TOGGLE      WO   write 1s: invert those OUT bits (atomic)
//     0x28 INT_EN      RW   interrupt enable per pin (INT_STATUS bits that
//                       raise irq_o), reset 0x0
//     0x2C RISE_EN     RW   a rising edge of the pin sets INT_STATUS, reset
//                       0x0
//     0x30 FALL_EN     RW   a falling edge of the pin sets INT_STATUS, reset
//                       0x0
//     0x34 INT_STATUS  W1C  edges seen per pin; write 1 to clear, reset 0x0
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-20
module gpio_regs #(
  parameter int WIDTH = 16  // number of pins (1..32)
) (
  input  logic             aclk,             // clock
  input  logic             aresetn,          // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  axil_if.slave s_axil,
  // r: gpio_regs_if.regs (src/include/gpio_regs_if.sv) {out_i=sts_out out_o=cfg_out out_wr_o=cfg_out_wr dir_o=cfg_dir dir_wr_o=cfg_dir_wr in_i=sts_in set_o=cfg_set set_wr_o=cfg_set_wr clear_o=cfg_clear clear_wr_o=cfg_clear_wr toggle_o=cfg_toggle toggle_wr_o=cfg_toggle_wr int_en_o=cfg_int_en int_en_wr_o=cfg_int_en_wr rise_en_o=cfg_rise_en rise_en_wr_o=cfg_rise_en_wr fall_en_o=cfg_fall_en fall_en_wr_o=cfg_fall_en_wr int_status_o=cfg_int_status int_status_wr_o=cfg_int_status_wr int_status_set_i=sts_int_status_set}
  gpio_regs_if.regs r
);
  // register signals, joined to the interface r
  logic [WIDTH-1:0] out_i;
  logic [WIDTH-1:0] out_o;
  logic out_wr_o;
  logic [WIDTH-1:0] dir_o;
  logic dir_wr_o;
  logic [WIDTH-1:0] in_i;
  logic [WIDTH-1:0] set_o;
  logic set_wr_o;
  logic [WIDTH-1:0] clear_o;
  logic clear_wr_o;
  logic [WIDTH-1:0] toggle_o;
  logic toggle_wr_o;
  logic [WIDTH-1:0] int_en_o;
  logic int_en_wr_o;
  logic [WIDTH-1:0] rise_en_o;
  logic rise_en_wr_o;
  logic [WIDTH-1:0] fall_en_o;
  logic fall_en_wr_o;
  logic [WIDTH-1:0] int_status_o;
  logic int_status_wr_o;
  logic [WIDTH-1:0] int_status_set_i;
  assign out_i = r.sts_out;
  assign r.cfg_out = out_o;
  assign r.cfg_out_wr = out_wr_o;
  assign r.cfg_dir = dir_o;
  assign r.cfg_dir_wr = dir_wr_o;
  assign in_i = r.sts_in;
  assign r.cfg_set = set_o;
  assign r.cfg_set_wr = set_wr_o;
  assign r.cfg_clear = clear_o;
  assign r.cfg_clear_wr = clear_wr_o;
  assign r.cfg_toggle = toggle_o;
  assign r.cfg_toggle_wr = toggle_wr_o;
  assign r.cfg_int_en = int_en_o;
  assign r.cfg_int_en_wr = int_en_wr_o;
  assign r.cfg_rise_en = rise_en_o;
  assign r.cfg_rise_en_wr = rise_en_wr_o;
  assign r.cfg_fall_en = fall_en_o;
  assign r.cfg_fall_en_wr = fall_en_wr_o;
  assign r.cfg_int_status = int_status_o;
  assign r.cfg_int_status_wr = int_status_wr_o;
  assign int_status_set_i = r.sts_int_status_set;
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "GPIO";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_OUT = 8'h10;
  localparam logic [7:0] A_DIR = 8'h14;
  localparam logic [7:0] A_IN = 8'h18;
  localparam logic [7:0] A_SET = 8'h1C;
  localparam logic [7:0] A_CLEAR = 8'h20;
  localparam logic [7:0] A_TOGGLE = 8'h24;
  localparam logic [7:0] A_INT_EN = 8'h28;
  localparam logic [7:0] A_RISE_EN = 8'h2C;
  localparam logic [7:0] A_FALL_EN = 8'h30;
  localparam logic [7:0] A_INT_STATUS = 8'h34;
  localparam int MAP_WORDS = 14;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  wire unused_addr_lsbs = &{1'b0, wr_addr[1:0], rd_addr[1:0]};   // word access: the byte offset is not decoded
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(8)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] out_q;
  logic [31:0] dir_q;
  logic [31:0] set_q;
  logic [31:0] clear_q;
  logic [31:0] toggle_q;
  logic [31:0] int_en_q;
  logic [31:0] rise_en_q;
  logic [31:0] fall_en_q;
  logic [31:0] int_status_q;
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      out_q <= '0;
      out_wr_o <= 1'b0;
      dir_q <= 32'h0;
      dir_wr_o <= 1'b0;
      set_q <= '0;
      set_wr_o <= 1'b0;
      clear_q <= '0;
      clear_wr_o <= 1'b0;
      toggle_q <= '0;
      toggle_wr_o <= 1'b0;
      int_en_q <= 32'h0;
      int_en_wr_o <= 1'b0;
      rise_en_q <= 32'h0;
      rise_en_wr_o <= 1'b0;
      fall_en_q <= 32'h0;
      fall_en_wr_o <= 1'b0;
      int_status_q <= 32'h0;
      int_status_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_IN);   // writes to read-only words: SLVERR
      begin
        out_wr_o <= wr_en && wa == A_OUT;
        if (wr_en && wa == A_OUT) out_q <= (out_q & ~wmask) | (wr_data & wmask);
      end
      begin
        dir_wr_o <= wr_en && wa == A_DIR;
        if (wr_en && wa == A_DIR) dir_q <= (dir_q & ~wmask) | (wr_data & wmask);
      end
      begin
        set_wr_o <= wr_en && wa == A_SET;
        if (wr_en && wa == A_SET) set_q <= (set_q & ~wmask) | (wr_data & wmask);
      end
      begin
        clear_wr_o <= wr_en && wa == A_CLEAR;
        if (wr_en && wa == A_CLEAR) clear_q <= (clear_q & ~wmask) | (wr_data & wmask);
      end
      begin
        toggle_wr_o <= wr_en && wa == A_TOGGLE;
        if (wr_en && wa == A_TOGGLE) toggle_q <= (toggle_q & ~wmask) | (wr_data & wmask);
      end
      begin
        int_en_wr_o <= wr_en && wa == A_INT_EN;
        if (wr_en && wa == A_INT_EN) int_en_q <= (int_en_q & ~wmask) | (wr_data & wmask);
      end
      begin
        rise_en_wr_o <= wr_en && wa == A_RISE_EN;
        if (wr_en && wa == A_RISE_EN) rise_en_q <= (rise_en_q & ~wmask) | (wr_data & wmask);
      end
      begin
        fall_en_wr_o <= wr_en && wa == A_FALL_EN;
        if (wr_en && wa == A_FALL_EN) fall_en_q <= (fall_en_q & ~wmask) | (wr_data & wmask);
      end
      begin
        int_status_wr_o <= wr_en && wa == A_INT_STATUS;
        int_status_q <= ((wr_en && wa == A_INT_STATUS) ? int_status_q & ~(wr_data & wmask) : int_status_q) | 32'(int_status_set_i);   // a set wins over a clear
      end
    end
  end
  assign out_o = out_q[WIDTH-1:0];
  assign dir_o = dir_q[WIDTH-1:0];
  assign set_o = set_q[WIDTH-1:0];
  assign clear_o = clear_q[WIDTH-1:0];
  assign toggle_o = toggle_q[WIDTH-1:0];
  assign int_en_o = int_en_q[WIDTH-1:0];
  assign rise_en_o = rise_en_q[WIDTH-1:0];
  assign fall_en_o = fall_en_q[WIDTH-1:0];
  assign int_status_o = int_status_q[WIDTH-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_OUT: rd_data = 32'(out_i);
      A_DIR: rd_data = 32'(dir_q[WIDTH-1:0]);
      A_IN: rd_data = 32'(in_i);
      A_INT_EN: rd_data = 32'(int_en_q[WIDTH-1:0]);
      A_RISE_EN: rd_data = 32'(rise_en_q[WIDTH-1:0]);
      A_FALL_EN: rd_data = 32'(fall_en_q[WIDTH-1:0]);
      A_INT_STATUS: rd_data = 32'(int_status_q[WIDTH-1:0]);
      default: begin
      end
    endcase
  end
endmodule
